    "inlineSchema": "model Client {\n  id              String    @id @default(uuid())\n  fullname        String\n  phone           String    @unique\n  address         String?\n  latitude        Float?\n  longitude       Float?\n  lastSellingDate DateTime?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  deletedAt       DateTime?\n\n  debtByCurrency ClientDebt[]\n\n  @@index([fullname])\n}\n\n// Har bir (mijoz + valyuta) juftligi uchun bitta qator.\n// Sotuv / to'lov / qaytaruv har safar shu yerdagi amount ni oshiradi yoki kamaytiradi.\nmodel ClientDebt {\n  id         String @id @default(uuid())\n  clientId   String\n  currencyId String\n  amount     Int    @default(0)\n\n  client   Client   @relation(fields: [clientId], references: [id])\n  currency Currency @relation(fields: [currencyId], references: [id])\n\n  @@unique([clientId, currencyId])\n  @@index([currencyId])\n}\n\nmodel Currency {\n  id           String   @id @default(uuid())\n  name         String\n  symbol       String   @unique // UZS, USD...\n  exchangeRate Int // 1 birlik = necha so'm (UZS uchun 1)\n  isDefault    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Product bilan teskari bog'lanish (bazada ustun yaratmaydi)\n  costProducts      Product[]    @relation(\"ProductCost\")\n  saleProducts      Product[]    @relation(\"ProductSale\")\n  wholesaleProducts Product[]    @relation(\"ProductWholesale\")\n  clientDebts       ClientDebt[]\n}\n\nenum DeviceStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  BLOCK\n}\n\nenum DeviceType {\n  DESKTOP\n  MOBILE\n  TABLET\n  OTHER\n}\n\nmodel Device {\n  id          Int          @id @default(autoincrement())\n  employeeId  String       @db.Uuid\n  employee    Employee     @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  tokenHash   String       @unique\n  fingerprint String?\n  type        DeviceType   @default(OTHER)\n  browser     String?\n  os          String?\n  userAgent   String?\n  ip          String?\n  country     String?\n  city        String?\n  status      DeviceStatus @default(PENDING)\n  requestedAt DateTime     @default(now())\n  decidedAt   DateTime?\n  lastSeenAt  DateTime?\n\n  @@index([employeeId, status, fingerprint])\n}\n\nmodel Employee {\n  id           String   @id @default(uuid()) @db.Uuid\n  fullName     String\n  phone        String   @unique\n  passwordHash String\n  isSuperadmin Boolean  @default(false)\n  isActive     Boolean  @default(true)\n  pages        String[] @default([])\n  devices      Device[]\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel Product {\n  id          String  @id @default(uuid())\n  name        String\n  description String? @db.Text\n  image       String?\n\n  count     Int @default(0)\n  minAmount Int @default(0)\n\n  warehouseId String\n  warehouse   Warehouse @relation(fields: [warehouseId], references: [id])\n\n  costPrice      Decimal  @db.Decimal(18, 2)\n  costCurrencyId String\n  costCurrency   Currency @relation(\"ProductCost\", fields: [costCurrencyId], references: [id])\n\n  salePrice      Decimal  @db.Decimal(18, 2)\n  saleCurrencyId String\n  saleCurrency   Currency @relation(\"ProductSale\", fields: [saleCurrencyId], references: [id])\n\n  wholesalePrice      Decimal  @db.Decimal(18, 2)\n  wholesaleCurrencyId String\n  wholesaleCurrency   Currency @relation(\"ProductWholesale\", fields: [wholesaleCurrencyId], references: [id])\n\n  lastSellingDate  DateTime?\n  lastSellingPrice Decimal?  @db.Decimal(18, 2)\n  lastSellingCount Int?\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([name])\n}\n\nmodel Warehouse {\n  id        String    @id @default(uuid())\n  name      String\n  isMain    Boolean   @default(false)\n  createdAt DateTime  @default(now())\n  products  Product[]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n",
